import{useState}from'react';import{Alert,StyleSheet,Text,View}from'@/platform/react-native';import{useLocalSearchParams}from'@/router';import{useMutation,useQuery,useQueryClient}from'@tanstack/react-query';import{api}from'@/lib/api';import{Badge,Button,Card,Header,Input,Muted,Screen,SectionTitle,useAppTheme}from'@/components/UI';
export default function Proposal(){const{proposalId}=useLocalSearchParams<{proposalId:string}>();const{palette}=useAppTheme();const qc=useQueryClient();const[text,setText]=useState('');const[amendTitle,setAmendTitle]=useState('');const[amendBody,setAmendBody]=useState('');const q=useQuery<any>({queryKey:['proposal',proposalId],queryFn:async()=>(await api.get(`/governance/proposals/${proposalId}`)).data});const discuss=useMutation({mutationFn:()=>api.post(`/governance/proposals/${proposalId}/discussion`,{body:text}),onSuccess:()=>{setText('');qc.invalidateQueries({queryKey:['proposal',proposalId]})}});const amend=useMutation({mutationFn:()=>api.post(`/governance/proposals/${proposalId}/amendments`,{title:amendTitle,body:amendBody}),onSuccess:()=>{setAmendTitle('');setAmendBody('');qc.invalidateQueries({queryKey:['proposal',proposalId]})}});const x=q.data;if(!x)return <Screen><Header title="Proposal"/><Muted>Loading…</Muted></Screen>;return <Screen scroll><Header title={x.proposal.Title} subtitle="Transparent community decision process"/><Badge text={x.proposal.Status}/><Card><Text style={[s.body,{color:palette.text}]}>{x.proposal.Body}</Text></Card><SectionTitle>Discussion</SectionTitle>{x.discussions.map((d:any)=><Card key={d.Id}><Text style={{color:palette.text,fontWeight:'800'}}>{d.FirstName} {d.LastName}</Text><Muted>{d.Body}</Muted></Card>)}<Input value={text} onChangeText={setText} placeholder="Add to the discussion" multiline/><Button title="Comment" variant="secondary" onPress={()=>text.trim()&&discuss.mutate()}/><SectionTitle>Amendments</SectionTitle>{x.amendments.map((a:any)=><Card key={a.Id}><View style={{flexDirection:'row',justifyContent:'space-between'}}><Text style={{color:palette.text,fontWeight:'900'}}>{a.Title}</Text><Badge text={a.Status}/></View><Muted>{a.Body}</Muted></Card>)}<Input value={amendTitle} onChangeText={setAmendTitle} placeholder="Amendment title"/><Input value={amendBody} onChangeText={setAmendBody} placeholder="Proposed amendment" multiline/><Button title="Propose amendment" variant="secondary" onPress={()=>amendTitle&&amendBody&&amend.mutate()}/></Screen>};const s=StyleSheet.create({body:{fontSize:15,lineHeight:22}})
